/**
 * R2 (Cloudflare) configuration.
 *
 * R2 is S3-compatible, so every value here maps 1:1 to an S3 client config.
 * Secrets (ACCOUNT_ID / SECRET_ACCESS_KEY) are NEVER shipped to the browser.
 * The browser only ever receives short-lived presigned URLs generated by the
 * server (see api/r2/* in the Next.js layer, or a Supabase Edge Function).
 */

export const R2_ENV_VARS = {
  ACCOUNT_ID: 'R2_ACCOUNT_ID',
  ACCESS_KEY_ID: 'R2_ACCESS_KEY_ID',
  SECRET_ACCESS_KEY: 'R2_SECRET_ACCESS_KEY',
  BUCKET: 'R2_BUCKET',
  PUBLIC_BASE_URL: 'R2_PUBLIC_BASE_URL', // optional, for publicly readable assets
} as const;

export type R2Config = {
  accountId: string;
  accessKeyId: string;
  secretAccessKey: string;
  bucket: string;
  /** Optional custom endpoint. Defaults to https://<account>.r2.cloudflare.com */
  endpoint?: string;
  /** Optional public base URL for assets served directly from the bucket. */
  publicBaseUrl?: string;
};

function required(name: string, value: string | undefined): string {
  if (!value || value.startsWith('your-') || value.startsWith('REPLACE')) {
    throw new Error(
      `[r2] Missing required env var ${name}. See .env.example and R2_STORAGE.md.`,
    );
  }
  return value;
}

/**
 * Build an R2Config from process.env.
 * Safe to call on the server only — never import this module into the browser bundle.
 */
export function loadR2Config(env: NodeJS.ProcessEnv = process.env): R2Config {
  const accountId = required(R2_ENV_VARS.ACCOUNT_ID, env[R2_ENV_VARS.ACCOUNT_ID]);
  const accessKeyId = required(R2_ENV_VARS.ACCESS_KEY_ID, env[R2_ENV_VARS.ACCESS_KEY_ID]);
  const secretAccessKey = required(
    R2_ENV_VARS.SECRET_ACCESS_KEY,
    env[R2_ENV_VARS.SECRET_ACCESS_KEY],
  );
  const bucket = required(R2_ENV_VARS.BUCKET, env[R2_ENV_VARS.BUCKET]);

  return {
    accountId,
    accessKeyId,
    secretAccessKey,
    bucket,
    endpoint: `https://${accountId}.r2.cloudflare.com`,
    publicBaseUrl: env[R2_ENV_VARS.PUBLIC_BASE_URL],
  };
}

/** Convert an R2 object key to a public URL, when publicBaseUrl is configured. */
export function publicUrl(config: R2Config, key: string): string | undefined {
  if (!config.publicBaseUrl) return undefined;
  const base = config.publicBaseUrl.replace(/\/+$/, '');
  return `${base}/${key.replace(/^\/+/, '')}`;
}